queries.gold_sql:
with rev as (
  select s.seller_state, s.seller_id, sum(i.price) as revenue
  from order_items i join sellers s on s.seller_id = i.seller_id group by s.seller_state, s.seller_id),
ranked as (select *, rank() over (partition by seller_state order by revenue desc) as rk from rev)
select seller_state, seller_id, round(revenue, 2) as revenue from ranked where rk = 1 order by seller_state;

